-- ================================================================
-- BANKING ANALYTICS PROJECT - COMPLETE MYSQL SCRIPT
-- Dataset: banking_data.csv
-- Records: 20,000
-- Purpose: Loan approval, credit risk, default and customer analysis
-- ================================================================

DROP DATABASE IF EXISTS `BankingAnalytics`;
CREATE DATABASE `BankingAnalytics` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `BankingAnalytics`;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `banking_loan_applications`;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE `banking_loan_applications` (
    `ApplicationID` BIGINT NOT NULL AUTO_INCREMENT,
    `applicationdate` DATE NULL,
    `age` INT NULL,
    `annualincome` DECIMAL(18,8) NULL,
    `creditscore` DECIMAL(18,8) NULL,
    `employmentstatus` VARCHAR(100) NULL,
    `educationlevel` VARCHAR(100) NULL,
    `experience` INT NULL,
    `loanamount` DECIMAL(18,8) NULL,
    `loanduration` INT NULL,
    `maritalstatus` VARCHAR(100) NULL,
    `numberofdependents` INT NULL,
    `homeownershipstatus` VARCHAR(100) NULL,
    `monthlydebtpayments` INT NULL,
    `creditcardutilizationrate` DECIMAL(18,8) NULL,
    `numberofopencreditlines` INT NULL,
    `numberofcreditinquiries` INT NULL,
    `debttoincomeratio` DECIMAL(18,8) NULL,
    `bankruptcyhistory` INT NULL,
    `loanpurpose` VARCHAR(100) NULL,
    `previousloandefaults` INT NULL,
    `paymenthistory` INT NULL,
    `lengthofcredithistory` INT NULL,
    `savingsaccountbalance` DECIMAL(18,8) NULL,
    `checkingaccountbalance` DECIMAL(18,8) NULL,
    `totalassets` DECIMAL(18,8) NULL,
    `totalliabilities` DECIMAL(18,8) NULL,
    `monthlyincome` DECIMAL(18,8) NULL,
    `utilitybillspaymenthistory` DECIMAL(18,8) NULL,
    `jobtenure` INT NULL,
    `networth` DECIMAL(18,8) NULL,
    `baseinterestrate` DECIMAL(18,8) NULL,
    `interestrate` DECIMAL(18,8) NULL,
    `monthlyloanpayment` DECIMAL(18,8) NULL,
    `totaldebttoincomeratio` DECIMAL(18,8) NULL,
    `loanapproved` INT NULL,
    `riskscore` DECIMAL(18,8) NULL,
    `income_group` VARCHAR(100) NULL,
    `age_group` VARCHAR(100) NULL,
    `loan_amount_group` VARCHAR(100) NULL,
    `credit_score_group` VARCHAR(100) NULL,
    `debt_income_category` VARCHAR(100) NULL,
    `loan_risk_category` VARCHAR(100) NULL,
    `loan_to_income_ratio` DECIMAL(18,8) NULL,
    `monthly_income_derived` DECIMAL(18,8) NULL,
    `monthly_debt_burden` DECIMAL(18,8) NULL,
    `loanamount_category` VARCHAR(100) NULL,
    `DefaultFlag` INT NULL,
    `ApplicationStatus` VARCHAR(100) NULL,
    PRIMARY KEY (`ApplicationID`)
) ENGINE=InnoDB;

-- Insert dataset records in batches









































-- Helpful indexes
CREATE INDEX `idx_applicationdate` ON `banking_loan_applications` (`applicationdate`);
CREATE INDEX `idx_creditscore` ON `banking_loan_applications` (`creditscore`);
CREATE INDEX `idx_loanapproved` ON `banking_loan_applications` (`loanapproved`);
CREATE INDEX `idx_DefaultFlag` ON `banking_loan_applications` (`DefaultFlag`);
CREATE INDEX `idx_ApplicationStatus` ON `banking_loan_applications` (`ApplicationStatus`);
CREATE INDEX `idx_loanpurpose` ON `banking_loan_applications` (`loanpurpose`);
CREATE INDEX `idx_employmentstatus` ON `banking_loan_applications` (`employmentstatus`);
CREATE INDEX `idx_loan_risk_category` ON `banking_loan_applications` (`loan_risk_category`);
CREATE INDEX `idx_credit_score_group` ON `banking_loan_applications` (`credit_score_group`);

-- ================================================================
-- VALIDATION QUERIES
-- ================================================================

-- 1. Preview records
SELECT * FROM `banking_loan_applications` LIMIT 10;


-- 2. Total applications
SELECT COUNT(*) AS total_applications FROM `banking_loan_applications`;


-- 3. Date range
SELECT MIN(applicationdate) AS first_application, MAX(applicationdate) AS last_application FROM `banking_loan_applications`;


-- 4. Check duplicate business rows
SELECT applicationdate, age, annualincome, loanamount, COUNT(*) AS duplicate_count
FROM `banking_loan_applications`
GROUP BY applicationdate, age, annualincome, loanamount
HAVING COUNT(*) > 1
ORDER BY duplicate_count DESC;


-- 5. Null-value check for important columns
SELECT
SUM(applicationdate IS NULL) AS missing_application_date,
SUM(age IS NULL) AS missing_age,
SUM(annualincome IS NULL) AS missing_annual_income,
SUM(creditscore IS NULL) AS missing_credit_score,
SUM(loanamount IS NULL) AS missing_loan_amount,
SUM(ApplicationStatus IS NULL) AS missing_application_status
FROM `banking_loan_applications`;


-- 6. Overall KPI summary
SELECT
COUNT(*) AS total_applications,
SUM(loanapproved) AS approved_applications,
COUNT(*) - SUM(loanapproved) AS rejected_applications,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
SUM(DefaultFlag) AS total_defaults,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct,
ROUND(AVG(annualincome), 2) AS avg_annual_income,
ROUND(AVG(loanamount), 2) AS avg_loan_amount,
ROUND(AVG(creditscore), 2) AS avg_credit_score
FROM `banking_loan_applications`;


-- 7. Application status distribution
SELECT ApplicationStatus, COUNT(*) AS applications,
ROUND(100 * COUNT(*) / (SELECT COUNT(*) FROM `banking_loan_applications`), 2) AS percentage
FROM `banking_loan_applications`
GROUP BY ApplicationStatus
ORDER BY applications DESC;


-- 8. Approval analysis by loan purpose
SELECT loanpurpose,
COUNT(*) AS applications,
SUM(loanapproved) AS approvals,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(AVG(loanamount), 2) AS avg_loan_amount
FROM `banking_loan_applications`
GROUP BY loanpurpose
ORDER BY approval_rate_pct DESC;


-- 9. Approval analysis by employment status
SELECT employmentstatus,
COUNT(*) AS applications,
SUM(loanapproved) AS approvals,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct
FROM `banking_loan_applications`
GROUP BY employmentstatus
ORDER BY approval_rate_pct DESC;


-- 10. Approval analysis by credit score group
SELECT credit_score_group,
COUNT(*) AS applications,
SUM(loanapproved) AS approvals,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(AVG(loanamount), 2) AS avg_loan_amount
FROM `banking_loan_applications`
GROUP BY credit_score_group
ORDER BY approval_rate_pct DESC;


-- 11. Default rate by risk category
SELECT loan_risk_category,
COUNT(*) AS customers,
SUM(DefaultFlag) AS defaults,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY loan_risk_category
ORDER BY default_rate_pct DESC;


-- 12. Default rate by credit score group
SELECT credit_score_group,
COUNT(*) AS customers,
SUM(DefaultFlag) AS defaults,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY credit_score_group
ORDER BY default_rate_pct DESC;


-- 13. Default rate by debt-to-income category
SELECT debt_income_category,
COUNT(*) AS customers,
SUM(DefaultFlag) AS defaults,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY debt_income_category
ORDER BY default_rate_pct DESC;


-- 14. Default rate by loan purpose
SELECT loanpurpose,
COUNT(*) AS applications,
SUM(DefaultFlag) AS defaults,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY loanpurpose
ORDER BY default_rate_pct DESC;


-- 15. Income group analysis
SELECT income_group,
COUNT(*) AS customers,
ROUND(AVG(annualincome), 2) AS avg_annual_income,
ROUND(AVG(loanamount), 2) AS avg_loan_amount,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY income_group
ORDER BY avg_annual_income;


-- 16. Age group analysis
SELECT age_group,
COUNT(*) AS customers,
ROUND(AVG(creditscore), 2) AS avg_credit_score,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY age_group
ORDER BY age_group;


-- 17. Home ownership analysis
SELECT homeownershipstatus,
COUNT(*) AS applications,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY homeownershipstatus
ORDER BY applications DESC;


-- 18. Marital status analysis
SELECT maritalstatus,
COUNT(*) AS applications,
ROUND(AVG(numberofdependents), 2) AS avg_dependents,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY maritalstatus;


-- 19. Loan duration analysis
SELECT loanduration,
COUNT(*) AS applications,
ROUND(AVG(loanamount), 2) AS avg_loan_amount,
ROUND(AVG(monthlyloanpayment), 2) AS avg_monthly_payment,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY loanduration
ORDER BY loanduration;


-- 20. Monthly debt burden analysis
SELECT
CASE
    WHEN monthly_debt_burden < 0.10 THEN 'Low'
    WHEN monthly_debt_burden < 0.20 THEN 'Moderate'
    WHEN monthly_debt_burden < 0.30 THEN 'High'
    ELSE 'Very High'
END AS burden_group,
COUNT(*) AS applications,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY burden_group
ORDER BY default_rate_pct DESC;


-- 21. Previous loan defaults analysis
SELECT previousloandefaults,
COUNT(*) AS customers,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY previousloandefaults
ORDER BY previousloandefaults;


-- 22. Bankruptcy history analysis
SELECT bankruptcyhistory,
COUNT(*) AS customers,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY bankruptcyhistory;


-- 23. Monthly trend analysis
SELECT
DATE_FORMAT(applicationdate, '%Y-%m') AS application_month,
COUNT(*) AS applications,
SUM(loanapproved) AS approvals,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY DATE_FORMAT(applicationdate, '%Y-%m')
ORDER BY application_month;


-- 24. Quarterly trend analysis
SELECT
YEAR(applicationdate) AS application_year,
QUARTER(applicationdate) AS application_quarter,
COUNT(*) AS applications,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY YEAR(applicationdate), QUARTER(applicationdate)
ORDER BY application_year, application_quarter;


-- 25. High-risk approved applications
SELECT ApplicationID, applicationdate, creditscore, annualincome,
loanamount, debttoincomeratio, loan_risk_category, DefaultFlag
FROM `banking_loan_applications`
WHERE loanapproved = 1
  AND (DefaultFlag = 1 OR loan_risk_category IN ('High Risk', 'Very High Risk'))
ORDER BY riskscore DESC, loanamount DESC
LIMIT 100;


-- 26. Top loan purposes by total loan amount
SELECT loanpurpose,
COUNT(*) AS applications,
ROUND(SUM(loanamount), 2) AS total_loan_amount,
ROUND(AVG(loanamount), 2) AS average_loan_amount
FROM `banking_loan_applications`
GROUP BY loanpurpose
ORDER BY total_loan_amount DESC;


-- 27. Approval rate using CTE
WITH purpose_summary AS (
    SELECT loanpurpose,
           COUNT(*) AS applications,
           SUM(loanapproved) AS approvals
    FROM `banking_loan_applications`
    GROUP BY loanpurpose
)
SELECT loanpurpose, applications, approvals,
       ROUND(100 * approvals / NULLIF(applications, 0), 2) AS approval_rate_pct
FROM purpose_summary
ORDER BY approval_rate_pct DESC;


-- 28. Rank loan purposes by default rate
WITH purpose_default AS (
    SELECT loanpurpose, ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
    FROM `banking_loan_applications`
    GROUP BY loanpurpose
)
SELECT loanpurpose, default_rate_pct,
       DENSE_RANK() OVER (ORDER BY default_rate_pct DESC) AS default_rate_rank
FROM purpose_default
ORDER BY default_rate_rank;


-- 29. Top 10 largest loans in each risk category
WITH ranked_loans AS (
    SELECT ApplicationID, loan_risk_category, loanamount, creditscore,
           ROW_NUMBER() OVER (
               PARTITION BY loan_risk_category
               ORDER BY loanamount DESC
           ) AS row_num
    FROM `banking_loan_applications`
)
SELECT *
FROM ranked_loans
WHERE row_num <= 10
ORDER BY loan_risk_category, row_num;


-- 30. Customers with high DTI and low credit score
SELECT ApplicationID, age, annualincome, creditscore,
       debttoincomeratio, loanamount, loan_risk_category, ApplicationStatus
FROM `banking_loan_applications`
WHERE debttoincomeratio >= 0.40
  AND creditscore < 650
ORDER BY debttoincomeratio DESC, creditscore ASC;


-- 31. Approval rate by education level
SELECT educationlevel,
COUNT(*) AS applications,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY educationlevel
ORDER BY approval_rate_pct DESC;


-- 32. Credit utilization analysis
SELECT
CASE
    WHEN creditcardutilizationrate < 0.30 THEN 'Low Utilization'
    WHEN creditcardutilizationrate < 0.60 THEN 'Moderate Utilization'
    ELSE 'High Utilization'
END AS utilization_group,
COUNT(*) AS applications,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY utilization_group
ORDER BY default_rate_pct DESC;


-- 33. Average financial position by application status
SELECT ApplicationStatus,
ROUND(AVG(savingsaccountbalance), 2) AS avg_savings,
ROUND(AVG(checkingaccountbalance), 2) AS avg_checking,
ROUND(AVG(totalassets), 2) AS avg_assets,
ROUND(AVG(totalliabilities), 2) AS avg_liabilities,
ROUND(AVG(networth), 2) AS avg_networth
FROM `banking_loan_applications`
GROUP BY ApplicationStatus;


-- 34. Business segmentation summary
SELECT loan_risk_category, income_group, credit_score_group,
COUNT(*) AS applications,
ROUND(100 * AVG(loanapproved), 2) AS approval_rate_pct,
ROUND(100 * AVG(DefaultFlag), 2) AS default_rate_pct
FROM `banking_loan_applications`
GROUP BY loan_risk_category, income_group, credit_score_group
ORDER BY default_rate_pct DESC, applications DESC;


-- 35. Final dashboard dataset
SELECT
    ApplicationID,
    applicationdate,
    age,
    annualincome,
    creditscore,
    employmentstatus,
    educationlevel,
    loanamount,
    loanpurpose,
    loanapproved,
    DefaultFlag,
    ApplicationStatus,
    income_group,
    age_group,
    credit_score_group,
    debt_income_category,
    loan_risk_category,
    loan_to_income_ratio,
    monthly_debt_burden
FROM `banking_loan_applications`;

